def extend_new(Stage,lesson,stages,lessons,sources):
    for row in NEW_MAPS:
        stages.append(Stage(row['name'],row['focus'],row['landmark']))
        source=len(sources);sources.append((row['source'],row['url']))
        for title,fact,q1,q2 in row['topics']:
            if title=='No todos vivieron la misma guerra':
                source=len(sources);sources.append(('Senado Federal · Lanceiros Negros','https://www12.senado.leg.br/noticias/materias/2023/03/15/paim-fala-sobre-aprovacao-de-lanceiros-negros-no-livro-dos-herois-da-patria'))
            questions=(q1,q2,
                (f'Para investigar «{title}», ¿qué ayuda a comprobar el archivo?','Consultar la fuente citada y contrastarla','Usar únicamente la apariencia del escenario','Elegir la respuesta por su longitud'),
                (f'¿Qué afirmación distingue la misión de «{title}» de una fuente histórica?','Crono es ficción; el archivo cita información comprobable','El mapa es una fotografía del pasado','Toda animación demuestra un hecho exacto'),
                (f'En «{title}», ¿qué exige una conclusión sobre toda una sociedad?','Comparar evidencias y reconocer sus límites','Generalizar a partir de un solo personaje','Ignorar a quienes no aparecen en el mapa'),
                (f'¿Cómo mejorarías una explicación sobre «{title}»?','Indicando procedencia, contexto y qué falta saber','Quitando fechas y referencias','Presentando una leyenda como certeza sin contrastarla'))
            lessons.append(lesson(title,fact,source,*questions))
